const fs = require('fs');
const path = '/tmp/stuttgart-live-lcp-reports';
const audits = ['first-contentful-paint','largest-contentful-paint','speed-index','total-blocking-time','cumulative-layout-shift','server-response-time'];
function read(label, profile, run) {
  const f = `${path}/${label}-${profile}-${run}.json`;
  const j = JSON.parse(fs.readFileSync(f, 'utf8'));
  const vals = {
    label, profile, run,
    score: Math.round((j.categories.performance.score ?? 0) * 100),
    fetchTime: j.fetchTime,
    finalUrl: j.finalDisplayedUrl || j.finalUrl,
  };
  for (const id of audits) vals[id] = j.audits[id]?.numericValue;
  const lcpEl = j.audits['largest-contentful-paint-element'];
  vals.lcpElementTitle = lcpEl?.title;
  vals.lcpElement = lcpEl?.details?.items?.[0]?.node?.selector || lcpEl?.details?.items?.[0]?.node?.snippet || null;
  vals.lcpElSnippet = lcpEl?.details?.items?.[0]?.node?.snippet || null;
  vals.lcpElSize = lcpEl?.details?.items?.[0]?.node?.nodeLabel || null;
  vals.lcpPhaseItems = j.audits['lcp-breakdown']?.details?.items || [];
  vals.networkRequests = j.audits['network-requests']?.details?.items?.length ?? null;
  vals.totalByteWeight = j.audits['total-byte-weight']?.numericValue ?? null;
  vals.errors = (j.runWarnings || []).concat(j.runtimeError ? [j.runtimeError.message] : []);
  return vals;
}
function median(items, key) {
  const sorted = [...items].sort((a,b) => a[key]-b[key]);
  return sorted[Math.floor(sorted.length/2)];
}
const rows = [];
for (const label of ['before','after']) for (const profile of ['mobile','desktop']) for (const run of [1,2,3]) rows.push(read(label, profile, run));
for (const profile of ['mobile','desktop']) {
  for (const label of ['before','after']) {
    const rs = rows.filter(r => r.profile === profile && r.label === label);
    const m = median(rs, 'largest-contentful-paint');
    console.log(`\n${label.toUpperCase()} ${profile.toUpperCase()} median by LCP: run ${m.run}`);
    console.log(JSON.stringify({
      score: m.score,
      fcp_ms: Math.round(m['first-contentful-paint']),
      lcp_ms: Math.round(m['largest-contentful-paint']),
      speedIndex_ms: Math.round(m['speed-index']),
      tbt_ms: Math.round(m['total-blocking-time']),
      cls: Number(m['cumulative-layout-shift']?.toFixed(3)),
      serverResponse_ms: Math.round(m['server-response-time'] || 0),
      requests: m.networkRequests,
      bytes_kb: Math.round((m.totalByteWeight || 0) / 1024),
      lcpElement: m.lcpElement,
      lcpSnippet: m.lcpElSnippet,
      warnings: m.errors
    }, null, 2));
    console.log('all runs:', rs.map(r => ({run:r.run, score:r.score, lcp:Math.round(r['largest-contentful-paint']), fcp:Math.round(r['first-contentful-paint']), tbt:Math.round(r['total-blocking-time']), cls:Number(r['cumulative-layout-shift']?.toFixed(3))})));
  }
}

const summary = {};
for (const profile of ['mobile','desktop']) {
  const b = median(rows.filter(r => r.profile === profile && r.label === 'before'), 'largest-contentful-paint');
  const a = median(rows.filter(r => r.profile === profile && r.label === 'after'), 'largest-contentful-paint');
  summary[profile] = {
    before_lcp_ms: Math.round(b['largest-contentful-paint']),
    after_lcp_ms: Math.round(a['largest-contentful-paint']),
    delta_lcp_ms: Math.round(a['largest-contentful-paint'] - b['largest-contentful-paint']),
    delta_lcp_pct: Number(((a['largest-contentful-paint'] - b['largest-contentful-paint']) / b['largest-contentful-paint'] * 100).toFixed(1)),
    before_score: b.score,
    after_score: a.score,
    before_run: b.run,
    after_run: a.run,
  };
}
console.log('\nSUMMARY');
console.log(JSON.stringify(summary, null, 2));
