const fs = require('fs');
const path = '/tmp/stuttgart-live-lcp-reports-seeded';
const metricIds = ['first-contentful-paint','largest-contentful-paint','speed-index','total-blocking-time','cumulative-layout-shift','server-response-time'];
function read(label, profile, run) {
  const f = `${path}/${label}-${profile}-${run}.json`;
  const j = JSON.parse(fs.readFileSync(f, 'utf8'));
  const out = {label, profile, run, file: f, score: Math.round(j.categories.performance.score * 100)};
  for (const id of metricIds) out[id] = j.audits[id]?.numericValue;
  out.requests = j.audits['network-requests']?.details?.items?.length ?? null;
  out.bytes = j.audits['total-byte-weight']?.numericValue ?? null;
  out.warnings = (j.runWarnings || []).concat(j.runtimeError ? [j.runtimeError.message] : []);
  const net = j.audits['network-requests']?.details?.items || [];
  out.promoHigh = net.filter(r => r.priority === 'High' && /cd393f225c0c895be8236a80401dd844|250715_WILHELMINE|1134-1064/.test(r.url)).map(r => r.url.split('/').pop());
  return out;
}
function medianBy(rows, key) { return [...rows].sort((a,b)=>a[key]-b[key])[Math.floor(rows.length/2)]; }
const all=[];
for (const profile of ['mobile','desktop']) for (const label of ['before','after']) for (const run of [1,2,3]) all.push(read(label, profile, run));
function fmt(row) {
  return {
    run: row.run,
    score: row.score,
    fcp_ms: Math.round(row['first-contentful-paint']),
    lcp_ms: Math.round(row['largest-contentful-paint']),
    speedIndex_ms: Math.round(row['speed-index']),
    tbt_ms: Math.round(row['total-blocking-time']),
    cls: Number(row['cumulative-layout-shift'].toFixed(3)),
    server_ms: Math.round(row['server-response-time'] || 0),
    requests: row.requests,
    kb: Math.round((row.bytes || 0)/1024),
    highPromo: row.promoHigh
  };
}
for (const profile of ['mobile','desktop']) {
