import { spawn } from "node:child_process"
import { mkdir, rm } from "node:fs/promises"

const [profileDir, targetUrl] = process.argv.slice(2)
if (!profileDir || !targetUrl) {
  console.error("Usage: node seed_chrome_consent.mjs PROFILE_DIR URL")
  process.exit(2)
}

const chromePath = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"
await rm(profileDir, { recursive: true, force: true })
await mkdir(profileDir, { recursive: true })

const chrome = spawn(chromePath, [
  "--headless=new",
  "--remote-debugging-port=0",
  `--user-data-dir=${profileDir}`,
  "--no-first-run",
  "--disable-default-apps",
  "--disable-background-networking",
  "--disable-sync",
  "about:blank"
], { stdio: [ "ignore", "ignore", "pipe" ] })

const browserWsUrl = await new Promise((resolve, reject) => {
  const timeout = setTimeout(() => reject(new Error("Timed out waiting for Chrome DevTools URL")), 10000)
  chrome.stderr.on("data", (chunk) => {
    const match = chunk.toString().match(/DevTools listening on (ws:\/\/\S+)/)
    if (!match) return
    clearTimeout(timeout)
    resolve(match[1])
  })
  chrome.on("exit", (code) => reject(new Error(`Chrome exited before DevTools was ready (${code})`)))
})

let nextId = 0
const pending = new Map()
const events = new EventTarget()
const socket = new WebSocket(browserWsUrl)
await new Promise((resolve, reject) => {
  socket.addEventListener("open", resolve, { once: true })
  socket.addEventListener("error", reject, { once: true })
})
socket.addEventListener("message", (event) => {
  const message = JSON.parse(event.data)
  if (message.id && pending.has(message.id)) {
    const { resolve, reject } = pending.get(message.id)
    pending.delete(message.id)
    if (message.error) reject(new Error(message.error.message))
    else resolve(message.result)
    return
  }
  if (message.method) events.dispatchEvent(new Event(message.method))
})

function send(method, params = {}) {
  const id = ++nextId
  socket.send(JSON.stringify({ id, method, params }))
  return new Promise((resolve, reject) => pending.set(id, { resolve, reject }))
}

await send("Target.createTarget", { url: "about:blank" }).then(async ({ targetId }) => {
  const { sessionId } = await send("Target.attachToTarget", { targetId, flatten: true })
  const sessionSend = (method, params = {}) => send("Target.sendMessageToTarget", {
    sessionId,
    message: JSON.stringify({ id: ++nextId, method, params })
  })

  // Use a direct WebSocket session for reliable responses from the page target.
  const targets = await fetch(browserWsUrl.replace(/^ws:/, "http:").replace(/\/devtools\/browser\/.+$/, "/json/list")).then((response) => response.json())
  const page = targets.find((target) => target.id === targetId)
  const pageSocket = new WebSocket(page.webSocketDebuggerUrl)
  let pageNextId = 0
  const pagePending = new Map()

  await new Promise((resolve, reject) => {
    pageSocket.addEventListener("open", resolve, { once: true })
    pageSocket.addEventListener("error", reject, { once: true })
  })
  pageSocket.addEventListener("message", (event) => {
    const message = JSON.parse(event.data)
    if (!message.id || !pagePending.has(message.id)) return
    const { resolve, reject } = pagePending.get(message.id)
    pagePending.delete(message.id)
    if (message.error) reject(new Error(message.error.message))
    else resolve(message.result)
  })

  const pageSend = (method, params = {}) => {
    const id = ++pageNextId
    pageSocket.send(JSON.stringify({ id, method, params }))
    return new Promise((resolve, reject) => pagePending.set(id, { resolve, reject }))
  }

  await pageSend("Page.enable")
  await pageSend("Network.enable")
  await pageSend("Page.navigate", { url: targetUrl })
  await new Promise((resolve) => setTimeout(resolve, 1500))
  await pageSend("Runtime.evaluate", {
    expression: "localStorage.setItem('stuttgart-live-consent-v1', JSON.stringify({ analytics: false, media: false }))",
    awaitPromise: true
  })
  await pageSend("Network.clearBrowserCache")
  pageSocket.close()
  await sessionSend("Runtime.discardConsoleEntries").catch(() => {})
})

socket.close()
chrome.kill("SIGTERM")

