const configureHeadingAttributes = () => {
  const headingBase = Trix.config.blockAttributes.heading1
  if (!headingBase) return

  HEADING_LEVELS.forEach(({ attribute, tagName }) => {
    Trix.config.blockAttributes[attribute] = {
      ...headingBase,
