const { rm, mkdir } = require('node:fs/promises')

;(async () => {
  const profileDir = '/tmp/stuttgart-lcp-js-verify-profile'
  const targetUrl = 'http://localhost:3000/'
  const chromePath = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'

  await rm(profileDir, { recursive: true, force: true })
  await mkdir(profileDir, { recursive: true })

  const chrome = spawn(chromePath, [
    '--headless=new',
    '--remote-debugging-port=0',
    `--user-data-dir=${profileDir}`,
    '--no-first-run',
    '--disable-default-apps',
    '--disable-background-networking',
    '--disable-sync',
    'about:blank'
  ], { stdio: ['ignore', 'ignore', 'pipe'] })

  try {
    const browserWsUrl = await new Promise((resolve, reject) => {
      const timeout = setTimeout(() => reject(new Error('Timed out waiting for Chrome DevTools URL')), 10000)
      chrome.stderr.on('data', chunk => {
        const match = chunk.toString().match(/DevTools listening on (ws:\/\/\S+)/)
        if (!match) return
        clearTimeout(timeout)
        resolve(match[1])
      })
      chrome.on('exit', code => reject(new Error(`Chrome exited before DevTools was ready (${code})`)))
    })

    const targetsUrl = browserWsUrl.replace(/^ws:/, 'http:').replace(/\/devtools\/browser\/.+$/, '/json/list')
    const targets = await fetch(targetsUrl).then(response => response.json())
    const page = targets.find(target => target.type === 'page')
    const socket = new WebSocket(page.webSocketDebuggerUrl)
    let nextId = 0
    const pending = new Map()

    await new Promise((resolve, reject) => {
      socket.addEventListener('open', resolve, { once: true })
      socket.addEventListener('error', reject, { once: true })
    })
    socket.addEventListener('message', event => {
      const message = JSON.parse(event.data)
      if (!message.id || !pending.has(message.id)) return
      const { resolve, reject } = pending.get(message.id)
      pending.delete(message.id)
      if (message.error) reject(new Error(message.error.message))
      else resolve(message.result)
    })
    const send = (method, params = {}) => {
      const id = ++nextId
      socket.send(JSON.stringify({ id, method, params }))
      return new Promise((resolve, reject) => pending.set(id, { resolve, reject }))
    }

    await send('Page.enable')
    await send('Runtime.enable')
    await send('Page.navigate', { url: targetUrl })
    await new Promise(resolve => setTimeout(resolve, 1200))
    await send('Runtime.evaluate', {
      expression: "localStorage.setItem('stuttgart-live-consent-v1', JSON.stringify({ analytics: false, media: false })); location.reload()",
      awaitPromise: false
    })
    await new Promise(resolve => setTimeout(resolve, 9500))
    const result = await send('Runtime.evaluate', {
      expression: `(() => ({
        readyState: document.readyState,
        publicScriptLoaded: !!document.querySelector('script[src*="/assets/public"]'),
        publicScriptSrc: document.querySelector('script[src*="/assets/public"]')?.getAttribute('src') || null,
        homepageLaneControllers: document.querySelectorAll('[data-controller~="homepage-lane"]').length,
        placeholders: document.querySelectorAll('.homepage-lane-initial-placeholder').length,
        renderedLaneCards: document.querySelectorAll('.home-featured-track .event-card:not(.homepage-lane-initial-placeholder), .genre-lane-track .genre-lane-card:not(.homepage-lane-initial-placeholder)').length
      }))()`,
      returnByValue: true
    })
    console.log(JSON.stringify(result.result.value, null, 2))
    socket.close()
  } finally {
    chrome.kill('SIGTERM')
  }
})().catch(error => {
  console.error(error)
  process.exit(1)
})
