const metricIds = {
  lcp: 'largest-contentful-paint',
  fcp: 'first-contentful-paint',
  si: 'speed-index',
  tbt: 'total-blocking-time',
  cls: 'cumulative-layout-shift',
  bytes: 'total-byte-weight'
}
function median(values) {
  const sorted = [...values].sort((a,b)=>a-b)
  return sorted[Math.floor(sorted.length / 2)]
}
function readDir(dir) {
  const runs = [1,2,3].map(i => JSON.parse(fs.readFileSync(`${dir}/mobile-${i}.json`, 'utf8')))
  const result = {}
  for (const [label,id] of Object.entries(metricIds)) {
    result[label] = runs.map(r => r.audits[id].numericValue)
    result[label + '_median'] = median(result[label])
  }
  result.lcpNode = runs[0].audits['lcp-breakdown-insight'].details.items.find(item => item.type === 'node')?.selector
  result.lcpSnippet = runs[0].audits['lcp-breakdown-insight'].details.items.find(item => item.type === 'node')?.snippet
  result.discovery = runs[0].audits['lcp-discovery-insight'].details.items.find(item => item.type === 'checklist')?.items
  const groups = new Map()
  for (const req of runs[0].audits['network-requests'].details.items) {
    const type = req.resourceType || req.mimeType || 'other'
    const g = groups.get(type) || { count: 0, transfer: 0 }
    g.count += 1
    g.transfer += req.transferSize || 0
    groups.set(type, g)
  }
  result.groups = [...groups].sort((a,b) => b[1].transfer - a[1].transfer).map(([type,g]) => ({ type, count: g.count, kb: Math.round(g.transfer / 1024) }))
  return result
}
const data = Object.fromEntries(Object.entries(series).map(([name,dir]) => [name, readDir(dir)]))
for (const [name,result] of Object.entries(data)) {
