(async () => {
const { spawn } = require('child_process');
const fs = require('fs');
const os = require('os');
const path = require('path');
const chromePath = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
const port = 9333 + Math.floor(Math.random() * 2000);
const profile = fs.mkdtempSync(path.join(os.tmpdir(), 'stuttgart-css-profile-'));
const chrome = spawn(chromePath, [`--remote-debugging-port=${port}`, `--user-data-dir=${profile}`, '--headless=new', '--no-first-run', '--disable-background-networking', '--disable-sync', 'about:blank'], { stdio: ['ignore', 'ignore', 'ignore'] });
const wait = ms => new Promise(resolve => setTimeout(resolve, ms));
async function pollJson(url) { const started = Date.now(); while (Date.now() - started < 10000) { try { const r = await fetch(url); if (r.ok) return await r.json(); } catch {} await wait(100); } throw new Error('timeout'); }
function connect(wsUrl) { const ws = new WebSocket(wsUrl); let id = 0; const pending = new Map(); const events = new Map(); ws.addEventListener('message', e => { const msg = JSON.parse(e.data); if (msg.id && pending.has(msg.id)) { const p = pending.get(msg.id); pending.delete(msg.id); msg.error ? p.reject(new Error(JSON.stringify(msg.error))) : p.resolve(msg.result || {}); } else if (msg.method && events.has(msg.method)) { for (const cb of events.get(msg.method)) cb(msg.params || {}); } }); return new Promise((resolve, reject) => { ws.addEventListener('open', () => resolve({ send(method, params = {}) { const callId = ++id; ws.send(JSON.stringify({ id: callId, method, params })); return new Promise((resolve, reject) => pending.set(callId, { resolve, reject })); }, once(method) { return new Promise(resolve => { const cb = params => { events.set(method, (events.get(method) || []).filter(item => item !== cb)); resolve(params); }; events.set(method, [...(events.get(method) || []), cb]); }); }, close() { ws.close(); } })); ws.addEventListener('error', reject); }); }
const expression = `(() => { const box = s => { const el = document.querySelector(s); if (!el) return null; const r = el.getBoundingClientRect(); return { y: Math.round(r.y*100)/100, height: Math.round(r.height*100)/100, width: Math.round(r.width*100)/100 }; }; return { frontendLoaded: Array.from(document.styleSheets).some(sheet => sheet.href && sheet.href.includes('/assets/frontend-')), nav: box('.app-nav'), main: box('#main-content'), hero: box('.promotion-banner-slider-section--hero .promotion-banner-poster'), heroCopy: box('.promotion-banner-slider-section--hero .promotion-banner-copy'), cta: box('.promotion-banner-slider-section--hero .promotion-banner-cta') }; })()`;
try {
  const version = await pollJson(`http://127.0.0.1:${port}/json/version`);
  const client = await connect(version.webSocketDebuggerUrl);
  const target = await fetch(`http://127.0.0.1:${port}/json/new?about:blank`, { method: 'PUT' }).then(r => r.json());
  const page = await connect(target.webSocketDebuggerUrl);
  await page.send('Page.enable'); await page.send('Runtime.enable'); await page.send('Network.enable'); await page.send('Network.setCacheDisabled', { cacheDisabled: true });
  await page.send('Emulation.setDeviceMetricsOverride', { width: 412, height: 915, deviceScaleFactor: 2.625, mobile: true, screenWidth: 412, screenHeight: 915 });
  await page.send('Emulation.setUserAgentOverride', { userAgent: 'Mozilla/5.0 (Linux; Android 11; Pixel 5) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Mobile Safari/537.36' });
  await page.send('Page.addScriptToEvaluateOnNewDocument', { source: `try { localStorage.setItem('stuttgart-live-consent-v1', '{"necessary":true}'); document.documentElement.classList.add('consent-preference-stored'); } catch (_) {}` });
  const load = page.once('Page.loadEventFired'); await page.send('Page.navigate', { url: 'http://localhost:3000/' }); await load; await wait(100);
  const before = (await page.send('Runtime.evaluate', { expression, returnByValue: true })).result.value;
  await wait(2600);
  const after = (await page.send('Runtime.evaluate', { expression, returnByValue: true })).result.value;
  const delta = Object.fromEntries(Object.keys(before).filter(k => typeof before[k] === 'object').map(k => [k, { dy: Math.round((after[k].y - before[k].y) * 100) / 100, dh: Math.round((after[k].height - before[k].height) * 100) / 100, dw: Math.round((after[k].width - before[k].width) * 100) / 100 }]));
  console.log(JSON.stringify({ before, after, delta }, null, 2));
  page.close(); client.close();
} finally { chrome.kill('SIGTERM'); }
})().catch(error => { console.error(error); process.exit(1); });
