body.page-public-events-index {
  --homepage-section-gap: 1.1rem;
  --homepage-content-max-width: 1360px;
  --homepage-header-max-width: 1480px;
  --homepage-content-padding-inline: 0.8rem;
  --homepage-header-padding-inline: 0.8rem;
  --ink: #0a2324;
  --ink-rgb: 10, 35, 36;
  --text-ink: #0a2324;
  color: var(--text-ink);
  overflow-x: clip;
}

body.page-public-events-index .app-nav {
  position: sticky;
  top: 0;
  z-index: 30;
  border-bottom: 0;
  background: linear-gradient(135deg, #2bd7cf 0%, #59e8de 100%);
  backdrop-filter: none;
}

body.page-public-events-index .app-nav-inner-homepage-poster {
  max-width: var(--homepage-header-max-width, 1480px);
  margin: 0 auto;
  padding: 0.82rem 0.8rem 0.95rem;
  display: grid;
  position: relative;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas:
    "brand brand"
    "center meta";
  gap: 0.68rem 0.8rem;
  align-items: start;
  background: transparent;
}

body.page-public-events-index .app-brand {
  grid-area: brand;
  align-self: start;
  justify-self: start;
  min-width: 0;
}

body.page-public-events-index .brand-wordmark-poster {
  display: inline-flex;
  align-items: baseline;
  color: #fff;
}

body.page-public-events-index .brand-wordmark-poster .brand-wordmark-city,
body.page-public-events-index .brand-wordmark-poster .brand-wordmark-live {
  font-family: "Oswald", "Arial Narrow", sans-serif;
  font-size: clamp(2.2rem, 9vw, 3.5rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 0.88;
}

body.page-public-events-index .brand-wordmark-poster .brand-wordmark-live {
  color: var(--ink);
  letter-spacing: -0.03em;
}

body.page-public-events-index .brand-tagline {
  color: rgba(255, 255, 255, 0.82);
}

body.page-public-events-index .app-nav-homepage-center {
  grid-area: center;
  display: flex;
  align-items: center;
  width: 100%;
  min-width: 0;
}

body.page-public-events-index .app-nav-search {
  width: 100%;
  max-width: none;
  min-width: 0;
  flex: 1 1 auto;
  justify-self: stretch;
}

body.page-public-events-index .public-search-filter {
  display: flex;
  align-items: center;
  width: 100%;
}

body.page-public-events-index .public-search-field {
  position: relative;
  width: 100%;
  z-index: 2;
  min-height: 2.7rem;
  border: 2px solid transparent;
  border-radius: 9999px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: none;
  overflow: visible;
}

body.page-public-events-index .public-search-input {
  position: relative;
  z-index: 2;
  width: 100%;
  min-width: 16rem;
  border: 0;
  border-radius: inherit;
  background: transparent;
  box-shadow: none;
  min-height: 2.7rem;
  padding-inline: 2.9rem 4.75rem;
  color: var(--ink);
  font-family: "Archivo Narrow", "Arial Narrow", sans-serif;
  font-size: 1.08rem;
  font-weight: 400;
  letter-spacing: 0.01em;
  text-indent: 0;
  text-transform: none;
}

body.page-public-events-index .public-search-placeholder {
  position: absolute;
  inset: 0;
  z-index: 1;
  display: flex;
  align-items: center;
  padding-inline: 2.9rem 4.75rem;
  color: rgba(10, 35, 36, 0.48);
  font-family: "Archivo Narrow", "Arial Narrow", sans-serif;
  font-size: 1.12rem;
  font-weight: 400;
  letter-spacing: 0.01em;
  pointer-events: none;
}

body.page-public-events-index .public-search-placeholder-hidden {
  opacity: 0;
}

body.page-public-events-index .public-search-placeholder-text {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

body.page-public-events-index .public-search-placeholder-cursor {
  width: 1px;
  height: 1.1em;
  margin-left: 0.08rem;
  background: currentColor;
}

body.page-public-events-index .public-search-input::placeholder {
  color: transparent;
  opacity: 0;
}

body.page-public-events-index .public-search-clear,
body.page-public-events-index .public-search-calendar,
body.page-public-events-index .public-search-icon {
  position: absolute;
  top: 50%;
  z-index: 3;
  transform: translateY(-50%);
  border: 0;
  background: transparent;
  box-shadow: none;
  line-height: 1;
}

body.page-public-events-index .public-search-clear {
  right: 0.9rem;
  margin-top: -1px;
  display: none;
  font-size: calc(1.35rem + 2px);
}

body.page-public-events-index .public-search-clear-visible {
  display: block;
}

body.page-public-events-index .public-search-icon {
  left: 0.18rem;
  width: 2.5rem;
  height: 2.5rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #111;
  font-size: 0;
}

body.page-public-events-index .public-search-icon svg {
  width: 1.34rem;
  height: 1.34rem;
  stroke: currentColor;
  fill: none;
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

body.page-public-events-index .public-search-calendar {
  right: calc(2.35rem - 10px);
  width: 2.5rem;
  height: 2.5rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 9999px;
  color: #cc4d8f;
}

body.page-public-events-index .public-search-calendar svg {
  width: 1.5rem;
  height: 1.5rem;
  stroke: currentColor;
  fill: none;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

body.page-public-events-index .public-search-overlay {
  position: absolute;
  top: calc(100% + 0.12rem - 2px);
  left: 20px;
  width: calc(100% - 40px);
  z-index: 1;
}

body.page-public-events-index .public-search-calendar-overlay {
  position: absolute;
  top: calc(100% + 0.42rem);
  right: 0;
  width: min(18.5rem, 100%);
  z-index: 35;
}

body.page-public-events-index .public-search-overlay-results {
  border-top: 0;
  border-top-left-radius: 0;
  border-top-right-radius: 0;
